def r(item, stage, job, cons, exc, says, does, blocks, rules, markets='', vol=3, val=3, risk=2):
    R.append(dict(item=item, stage=stage, job=job, constraint=cons, exception=exc, says=says, does=does,
                  blocks=blocks, rules=rules, markets=markets, vol=vol, val=val, risk=risk))

